INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, 1, 2.1, "ヤマト", -416.5, 3001100, 100, "2030/01/01 14:59:59", 130011, 3001, 0.0, "2024/10/31 12:00:00", "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, 4, 5.68, "ヤマト", -416.5, 3001101, 101, "2030/01/01 14:59:59", 130011, 3001, 0.0, "2024/10/31 12:00:00", "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, 1, 0.0, "ヤマト", -416.5, 3001102, 102, "2030/01/01 14:59:59", 130011, 3001, 0.0, "2024/10/31 12:00:00", "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, 1, 0.0, "フブキ", -416.5, 3002100, 100, "2030/01/01 14:59:59", 130211, 3002, 0.0, "2024/10/31 12:00:00", "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, 1, 0.0, "フブキ", -416.5, 3002101, 101, "2030/01/01 14:59:59", 130211, 3002, 0.0, "2024/10/31 12:00:00", "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, 5, 8.53, "フブキ", -416.5, 3002102, 102, "2030/01/01 14:59:59", 130211, 3002, 0.0, "2024/10/31 12:00:00", "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, 7, 5.67, "フブキ", -416.5, 3002103, 103, "2030/01/01 14:59:59", 130211, 3002, 0.0, "2024/10/31 12:00:00", "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, 1, 0.0, "フブキ", -416.5, 3002104, 104, "2030/01/01 14:59:59", 130211, 3002, 0.0, "2024/10/31 12:00:00", "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3, 3, 0.0, "フブキ", -416.5, 3002300, 300, "2030/01/01 14:59:59", 130211, 3004, 0.0, "2024/10/31 12:00:00", "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (7, 7, 0.0, "フブキ", -416.5, 3002400, 301, "2030/01/01 14:59:59", 130211, 3005, 0.0, "2024/10/31 12:00:00", "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, 2, 4.4, "フブキ", -416.5, 3003200, 200, "2030/01/01 14:59:59", 130211, 3003, 0.0, "2024/10/31 12:00:00", "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (7, 7, 0.0, "フブキ", -416.5, 3003201, 201, "2030/01/01 14:59:59", 130211, 3003, 0.0, "2024/10/31 12:00:00", "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, 1, 5.6, "フブキ", -416.5, 3003202, 202, "2030/01/01 14:59:59", 130211, 3003, 0.0, "2024/10/31 12:00:00", "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪");
